  "inlineSchema": "// ============================================================================\n// CA Office Document Automation System - Database Schema\n// Engine: SQLite (file-based, zero-admin, ideal for LAN single-server deploy)\n// ============================================================================\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"sqlite\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ---------------------------------------------------------------------------\n// Module 1: Template Management\n// ---------------------------------------------------------------------------\nmodel Category {\n  id        String     @id @default(cuid())\n  name      String     @unique\n  isSystem  Boolean    @default(false) // seeded defaults (Income Tax, GST, ...) cannot be deleted\n  createdAt DateTime   @default(now())\n  templates Template[]\n}\n\nmodel Template {\n  id            String    @id @default(cuid())\n  name          String\n  categoryId    String\n  category      Category  @relation(fields: [categoryId], references: [id])\n  keywords      String? // comma-separated tokens, indexed via TemplateKeyword for search\n  description   String?\n  fileLocation  String // relative path under TEMPLATE_FOLDER, e.g. templates/{id}.docx\n  originalName  String\n  status        String    @default(\"Active\") // Active | Deleted\n  version       Int       @default(1)\n  fileSizeBytes Int       @default(0)\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n  deletedAt     DateTime?\n\n  placeholders          TemplatePlaceholder[]\n  keywordEntries        TemplateKeyword[]\n  generationHistoryRows GenerationHistoryTemplate[]\n\n  @@index([status])\n  @@index([categoryId])\n  @@index([name])\n}\n\n// One row per (template, keyword) pair -> enables fast full-text style search\nmodel TemplateKeyword {\n  id         String   @id @default(cuid())\n  templateId String\n  template   Template @relation(fields: [templateId], references: [id], onDelete: Cascade)\n  keyword    String\n\n  @@index([keyword])\n}\n\n// ---------------------------------------------------------------------------\n// Module 2/3: Placeholder Detection + Mapping\n// ---------------------------------------------------------------------------\nmodel Placeholder {\n  id             String   @id @default(cuid())\n  name           String   @unique // \"Client Name\" (stored WITHOUT surrounding #)\n  validationType String   @default(\"Text\") // Text | Email | PAN | GSTIN | Mobile | PinCode | Date | Image\n  isImage        Boolean  @default(false)\n  createdAt      DateTime @default(now())\n\n  templates TemplatePlaceholder[]\n  mapping   PlaceholderMapping?\n}\n\n// Many-to-many: which templates use which placeholders\nmodel TemplatePlaceholder {\n  id            String      @id @default(cuid())\n  templateId    String\n  placeholderId String\n  template      Template    @relation(fields: [templateId], references: [id], onDelete: Cascade)\n  placeholder   Placeholder @relation(fields: [placeholderId], references: [id], onDelete: Cascade)\n\n  @@unique([templateId, placeholderId])\n}\n\n// Maps a placeholder to a Client Master field (system column or custom field)\nmodel PlaceholderMapping {\n  id             String      @id @default(cuid())\n  placeholderId  String      @unique\n  placeholder    Placeholder @relation(fields: [placeholderId], references: [id], onDelete: Cascade)\n  clientFieldKey String // matches ClientField.fieldKey, e.g. \"name\", \"custom_pan\"\n  updatedAt      DateTime    @updatedAt\n}\n\n// ---------------------------------------------------------------------------\n// Module 4: Client Management (expandable master)\n// ---------------------------------------------------------------------------\n// Core columns kept for query performance; ClientField/ClientCustomValue allow\n// adding new fields at runtime with zero code changes (EAV pattern).\nmodel Client {\n  id           String   @id @default(cuid())\n  name         String\n  addressLine1 String?\n  addressLine2 String?\n  clientType   String?\n  mobile       String?\n  email        String?\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  customValues      ClientCustomValue[]\n  generationHistory GenerationHistory[]\n\n  @@index([name])\n}\n\n// Definition of a dynamic/custom client-master field, configurable by admin\nmodel ClientField {\n  id         String   @id @default(cuid())\n  fieldKey   String   @unique // stable key used in mappings, e.g. \"custom_pan\"\n  label      String // display label, e.g. \"PAN Number\"\n  fieldType  String   @default(\"Text\") // Text | Email | Mobile | Date | PAN | GSTIN | PinCode\n  isSystem   Boolean  @default(false) // true for name/address1/address2/clientType/mobile/email\n  isRequired Boolean  @default(false)\n  sortOrder  Int      @default(0)\n  createdAt  DateTime @default(now())\n\n  values ClientCustomValue[]\n}\n\nmodel ClientCustomValue {\n  id       String      @id @default(cuid())\n  clientId String\n  fieldId  String\n  client   Client      @relation(fields: [clientId], references: [id], onDelete: Cascade)\n  field    ClientField @relation(fields: [fieldId], references: [id], onDelete: Cascade)\n  value    String?\n\n  @@unique([clientId, fieldId])\n}\n\n// ---------------------------------------------------------------------------\n// Module 10: Generation History\n// ---------------------------------------------------------------------------\nmodel GenerationHistory {\n  id                    String   @id @default(cuid())\n  clientId              String?\n  client                Client?  @relation(fields: [clientId], references: [id])\n  clientNameSnapshot    String // preserved even if client later renamed/deleted\n  placeholderValuesJson String // JSON: { \"Client Name\": \"ABC Pvt Ltd\", ... }\n  outputFolder          String\n  generatedAt           DateTime @default(now())\n\n  templates GenerationHistoryTemplate[]\n\n  @@index([generatedAt])\n  @@index([clientId])\n}\n\nmodel GenerationHistoryTemplate {\n  id                  String            @id @default(cuid())\n  generationHistoryId String\n  templateId          String\n  generatedFileName   String\n  generationHistory   GenerationHistory @relation(fields: [generationHistoryId], references: [id], onDelete: Cascade)\n  template            Template          @relation(fields: [templateId], references: [id])\n}\n\n// ---------------------------------------------------------------------------\n// Module 11: Application Settings (key/value, no hardcoded config)\n// ---------------------------------------------------------------------------\nmodel Setting {\n  key       String   @id\n  value     String\n  updatedAt DateTime @updatedAt\n}\n\n// ---------------------------------------------------------------------------\n// Admin auth for \"Manage Formats\" (Template Management password gate)\n// ---------------------------------------------------------------------------\nmodel AdminUser {\n  id           String   @id @default(cuid())\n  username     String   @unique\n  passwordHash String\n  role         String   @default(\"admin\")\n  createdAt    DateTime @default(now())\n}\n\n// ---------------------------------------------------------------------------\n// Application audit log (who changed what - lightweight, no user login system)\n// ---------------------------------------------------------------------------\nmodel AuditLog {\n  id         String   @id @default(cuid())\n  action     String // e.g. \"TEMPLATE_DELETE\", \"TEMPLATE_RESTORE\", \"SETTINGS_UPDATE\"\n  entityType String\n  entityId   String?\n  detail     String?\n  createdAt  DateTime @default(now())\n}\n",
